import {ListItem} from '@github-ui/list-view/ListItem'
import {ListItemDescription} from '@github-ui/list-view/ListItemDescription'
import {ListItemDescriptionItem} from '@github-ui/list-view/ListItemDescriptionItem'
import {ListItemLeadingVisual} from '@github-ui/list-view/ListItemLeadingVisual'
import {ListItemMainContent} from '@github-ui/list-view/ListItemMainContent'
import {ListItemTitle} from '@github-ui/list-view/ListItemTitle'
import {Link} from '@github-ui/react-router'
import {getIconColorClassName, getIconComponent} from '@github-ui/saved-views'
import {CopyIcon, KebabHorizontalIcon, TrashIcon} from '@primer/octicons-react'
import {ActionList, ActionMenu, IconButton, RelativeTime, useConfirm} from '@primer/react'
import {memo} from 'react'

import {LABELS} from '../../constants/labels'
import {useDeleteSavedViewMutation} from '../../hooks/use-delete-saved-view-mutation'
import {useDuplicateSavedViewDialog} from '../../hooks/use-duplicate-saved-view-dialog'
import {SAVED_VIEW_OPEN_SOURCES, type SavedViewOpenLocationState} from '../../hooks/use-saved-view-analytics'
import styles from './RepositoryViews.module.css'
import type {SavedView} from './types'

type ViewRowProps = {
  view: SavedView
  owner: string
  repo: string
}

function ViewRowComponent({view, owner, repo}: ViewRowProps) {
  const viewUrl = `/${owner}/${repo}/issues/views/${view.id}`
  const openFromIndexState: SavedViewOpenLocationState = {savedViewOpenSource: SAVED_VIEW_OPEN_SOURCES.index}
  const confirm = useConfirm()

  const {mutate: deleteView, isPending: isDeleting} = useDeleteSavedViewMutation({owner, repo})
  const {openDuplicateDialog, duplicateDialog} = useDuplicateSavedViewDialog({owner, repo})

  const handleDelete = async () => {
    const confirmed = await confirm({
      title: LABELS.views.deleteTitle,
      content: LABELS.views.deleteContent(view.name),
      confirmButtonContent: LABELS.views.deleteConfirmationButton,
      confirmButtonType: 'danger',
    })
    if (confirmed) deleteView({id: view.id})
  }

  return (
    <>
      <ListItem
        title={
          <ListItemTitle
            value={view.name}
            href={viewUrl}
            linkProps={{as: Link, to: viewUrl, state: openFromIndexState}}
          />
        }
        role="listitem"
        className={styles.viewRow}
        secondaryActions={
          <div className={styles.viewActions}>
            <ActionMenu>
              <ActionMenu.Anchor>
                <IconButton
                  icon={KebabHorizontalIcon}
                  aria-label={`${view.name} options`}
                  variant="invisible"
                  disabled={isDeleting}
                />
              </ActionMenu.Anchor>
              <ActionMenu.Overlay width="small">
                <ActionList>
                  <ActionList.Item onSelect={() => openDuplicateDialog(view)} disabled={isDeleting}>
                    <ActionList.LeadingVisual>
                      <CopyIcon />
                    </ActionList.LeadingVisual>
                    {LABELS.views.duplicate}
                  </ActionList.Item>
                  <ActionList.Item onSelect={handleDelete} disabled={isDeleting} variant="danger">
                    <ActionList.LeadingVisual>
                      <TrashIcon />
                    </ActionList.LeadingVisual>
                    {LABELS.views.delete}
                  </ActionList.Item>
                </ActionList>
              </ActionMenu.Overlay>
            </ActionMenu>
          </div>
        }
      >
        <ListItemLeadingVisual
          className={`${styles.viewLeadingVisual} ${getIconColorClassName(view.color)}`}
          icon={getIconComponent(view.icon)}
        />
        <ListItemMainContent>
          <ListItemDescription>
            <ListItemDescriptionItem>
              {view.creatorLogin ? <span>Created by {view.creatorLogin} &bull; </span> : null}
              <span>
                Last updated <RelativeTime datetime={view.updatedAt} />
              </span>
            </ListItemDescriptionItem>
          </ListItemDescription>
        </ListItemMainContent>
      </ListItem>
      {duplicateDialog}
    </>
  )
}

export const ViewRow = memo(ViewRowComponent)
